import java.util.Map;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;


/**
 * Black-Box API Integration Test (template-rendered v2)
 *
 * @target-controller CommunityController (src/main/java/com/tainted/community/web/CommunityController.java)
 * @target-api GET /internal/posts/{id}
 *
 * GET /internal/posts/{id} 엔드포인트 블랙박스 테스트
 * 정상 조회, 미존재 데이터, 에러 시나리오를 검증
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class GetPostBlackBoxTest {

    private Map<String, String> seed(TestInfo info) {
        return Map.of(
                "ID", "post" + testId(info));
    }

    private void arrange(Map<String, String> p) {
        executeSqlTemplate("sql/get-post-teardown.sql", p);
        executeSqlTemplate("sql/get-post-setup.sql", p);
    }

    @Test
    void NTC_getPost_ok(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .pathParam("id", p.get("ID"))
            .when()
                    .get("/internal/posts/{id}")
            .then()
                    .statusCode(200)
                    .body("id", equalTo("${ID}"))
                    .body("userId", equalTo("user123"))
                    .body("title", equalTo("Test Post Title"))
                    .body("category", equalTo("daily"))
                    .body("content", equalTo("This is test post content for black-box testing"))
                    .body("moodEmoji", equalTo("😊"))
                    .body("nickname", equalTo("TestUser"))
                    .body("likes", equalTo(5));
        } finally {
            executeSqlTemplate("sql/get-post-teardown.sql", p);
        }
    }

    @Test
    void ATC_getPost_notFound(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .pathParam("id", "nonexistent-post-id")
            .when()
                    .get("/internal/posts/{id}")
            .then()
                    .statusCode(404)
                    .body("status", equalTo(404))
                    .body("title", equalTo("Post not found"));
        } finally {
            executeSqlTemplate("sql/get-post-teardown.sql", p);
        }
    }
}

